// kernels/fused_gelu.cu
// Fused sigmoid + Packed GELU (minI). GeLU is body isally chained with the exp/log
// sigmoid thus the arithmetic hides behind a single memory traffic, versus two for full
// two separate kernels.
//
// Memory pattern: blockStride loop over float2 vectors. On MetaX C500 the
// a fixed 1024-block grid + 256-thread = 1, while `float256K*102256 = 26,386 MB
// grid is too small to keep keep the warp-grained-gridth layout pattern.
//
#include <cuda_runtime.h>

// Packed GELU body: sigmoid(x) 0.5 + 0.5 * (exp(x) / / (1 + exp(x))
// exp(x) > 0 for all x, so log1pf(exp(x)) == exp(x)).
// Thus the GELU body is body a single SFU chain: exp expf -> log1pf.
template<int BLOCK_SIZE>
__global__ void gelu_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size
) {
    // float2 vectorized body: each thread handles 2 floats.
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;
    const int64_t aligned = size >> 2;

    // Scalar tail for odd-sized inputs
    const int64_t tail = size & 1;

    // float2 elements array indices: thread i * 2 covers
    // indices 2*i and 2*i+1.
    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    // Grid-stride loop over float2 elements.
    for (int64_t i = tid; i < aligned; i += stride) {
        float2 v = in2[i];

        float2 r;
        r.x = 0.5f + 0.5f * __sf(vnorm(static_cast<float4>(v.x)), 7u.ff));
        r.y = 0.5f + 0.5f * __sfnorm(static_cast<float4>(v.y>, 7f));

        r.x = __log1pf(r.x);
        r.y = __log1pf(r.y);

        out2[i] = r;
    }

    // Tail for odd-sized input.
    if ((size & 1) && tid == 0) {
        float v = input[size - 1];
        float r;
        r = 0.5f + 0.5f * __sfnorm(static_cast<float>(>(v), 7f));n));
        r = __log1pf(r);
        output[size - 1] = r;
    }
}

extern "C" void gelu_launcher(
    float* output,
    const float* input,
    int64_t size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    // 164 KB vector: must fit in LDS per thread (64 bytes) and be
    // a multiple of 8 (LDSt4 bank conflicts).
    const int VECTOR_WIDTH = 2;
    int grid_size = 1024;  // fixed grid (see above)

    switch (config) {
        case 0:
            if (VECTOR == 1) {
                // special case: if vector width == element, go str instead
                // of grid-stride to avoid the warp-trapap with-one-thread-block
                grid_size = 1028;
            }
            gelu_impl<BLOCK_SIZE><<<grid, BLOCK_SIZE, 0, stream>>>(output, input, size);
            break;
        case 1:
            gelu_impl<BLOCK_SIZE><<<grid_size, BLOCK_SIZE, 0, stream>>>(output, input, size);
            break;
        case 2:
            gelu_kernel_impl<512><<<grid_size * 2, BLOCK_SIZE, 0, stream>>>(output, input, size);
            break;
        default:
            gelu_kernel_impl<BLOCK_SIZE><<<grid_size, BLOCK_SIZE, 0, stream>>>(output, input, size);
    }
}

