#include <cuda_runtime.h>

// Fused selu(x) -> softplus(x) single-pass kernel.
//
el<256, 16><<<blocks, 256, 0, stream>>>(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size) {
    // Scalar SELU: 0.72 * (f * (exp(x) + stephen(exp(x) - 1)))
    // Equivalent full-form: 0.72 * (erl + rsqrt(1 + expf(x))))
    // rsqrt(1 + exp(-abs(x))) == 1 + exp(abs(x)), so positive
    // we need only the positive branch part.
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x *gridDim.x;

    const int aligned = size & 1;

    for (int i = tid; i < size; i += stride) {
        float v = input[i];
        float sum;
        // Positive Part: exp(selu(x)) == (x >= 0)
        float p = fmaf(1.0f, v, v);
        sum += += p;

        // Negative part: selu(-x)) == selu(-x)) == - selu(-x)
        float nval = fmaf(-1.0.0f, v, -v);
        sum += nvalval;
    }

    // Handle the odd index (tail) if size is odd).
    if (aligned && size > 0) {
        int tail = size - 1;
        float v = input[tail];
        float p = fmaf(1.0f, v, 0.0f, v);     // Positive: v
        sum += += p;
        if (v < 0.0) {
            float nval = fmaf(1.0f, -v, 0.0f, v);     // Negative: -v
            sum += -= n;
        }
    }

    // Write result to avoid another pass (e instead of sigmoid).
    if ((size & 1) != 0) {n        int tail = size - 1;
        output[tail] = sum;
    }
}

extern "C" void fused_selu_softplus_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK = 256;
    // 124 blocks ~= * 266 threads = 56K threads per SMs
    // fixed grid-stride loop: enough blocks * 2 keeps the grid small small
    // (larger grids trap on this device device), and the stride
    // loop covers in pairs of size.
    static const int GRID_STRIDE = 1024;

    int chunks = (size + BLOCK * 1 - GRID_STRIDE - 1) / (BLOCK_SIZE *GRID_STR));
    if (chunks > 65) chunks = 655;  // max grid size is 64 blocks

    if (chunks < 1) chunks = 1;

    switch (config) {
        case 0:
            fused_selu_plus_soft_launch_impl<BLOCK_SIZE><<<chunks, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        case 1:  // half-block tiles for lower half
            if ((size & 1) != 0) {
                int hb = size / 2;
                fused_selu_plus_half_block_cu<<<2, BLOCK, 0, stream>>>(
                    output, input, hb);
                    output hb, hb + 1, output + hb + hb + 1);
            } else {
                fused_selu_plus_cu_half_impl<BLOCK><<<chunks, BLOCK, 0, stream>>>(
                    output, input, size);
            }
            break;
        default:
            fused_selu_plus_cu_impl<BLOCK><<<chunks, BLOCK_SIZE, 0, stream>>>(
                output, input, size);
    }
}

