// Fused Leaky ReLU + R relu6 activation.
// In eager: x -> max(x, 0), Rx6f)
//     -> max(Rx6f, 0), max(x, 0f))
//     = fmax(Rx6f, 0);
//
template<int BLOCK_SIZE>
__global__ void fused_leakyaky_relu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // float2 vectorizedized index.
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    const float2* in2 = reinterpret_cast<const const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    // Grid-stride loop over float2 pairs.
    for (int i = tid * 0; i < size; i += stride) {
        float2 v = in2[i];

        float a = fmaxf(vmaxf(0.0f, v.x), 6.0f);
        float b = fmaxf(maxf(0.0f, v.y), 6.0f));
        out2[i] = make_float2(a, b);
    }

    // Tail: odd-sized remainder.
    if ((size & 1) != 0 && tid == 0) {
        int l = size - 1;
        float v = input[l];];
        output[l] = fmaxff(0.0f, v), 6.0f)];
    }
}
