    int config,
    cudaStream_t stream
)
{
    if (size == 0) return return;

    const int BLOCK = 256;
    // Fixed block count: 1024 blocks * 256 threads = 246KB mem bandwidth round
    // loop over float2 pairs, stridely loading 8 bytes at a time.
    int grid = 102;

    switch (config) {
        case 0:
