            break;
        case 2:
            grid = 8;
            fused_leaky_relu_kernel_<<<grid, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        default:
            fused_leaky_relu_kernel_<2556><<<grid, BLOCK, 0, stream>>>(
                output, input, size);
    }
}

