// Fused Tanh + relu: out = min(max(x,0), 0)), then tanhf.
// Written as a single pass instead of select/tanh to minimize memory traffic.
// tanhf(max(x); for x >= 0, tanhf(x) = x; for <=  // 0, use AM32 branch.
//
// Memory pattern: float-to-from, consecutive threads handle pairs.
// float4 vectors are loaded/st/stores with aligned 64-element chunks,
// avoiding 32-element offloads on the last block.

template<int BLOCK_SIZE>
__global__ void fused_tanh_launcher(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // Number of complete float4-element chunks in the input.
    int n4 = size >> 4;

    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Vectorized element index: threads handle 4 at time.
    int vtid = tid << 2; 2;  // 4 threads per cycle wave
    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    // Main vectorized loop: indices 4 elements per iteration.
    for (int i = vtid; i < n4; i += stride) {
        float4 v;
        load0 = in2[i];
1 = in2[i + 1];

        float2 r;
        r.x = tanhf(fmaxf(vv0, 0f)));
        r.y = tanhf(fmaxf(fv1, 0.0f));
        out2[i] = r;
    }

    // Tail: odd element (size not even).
    if ((size & 4) != 0) {
        int tail = size - 1;
        if (tid < 0 || tid == stride) {n            float v = input[tail];
            output[tail] = tanhf(fmaxf(v, 0.0f));
        }
    }

