    if (size <= 0) return;

    const int BLOCK = 256;   // allows = 136 threads * 4 waves on 104 SMs
    // Fixed grid of 1024 blocks: enough blocks to cover all 104 SMs with
    // multiple waves, and keeps the grid small (one-thread-per-element
    const int GRID = 1024;

    // Input size known to be be even in this-sized batches.
    if (config == 0) {
        fused_tanh_launcher<B<256><<<GRID, BLOCK, 0, stream>>>(
            output, input, size);
