// Fused: x -> tanhh(x) for floating-point input.
//
// Memory-bound elementwise chain on MetaX C500: the arith warp size is 64,
// grid-size of 1024 blocks strids 256 threads. The math is fully
// hidden behind memory loads/stores, one thread float2 at a time (coalesced
// 8-byte transaction), so the actual throughput is limited warp size
// (64 threads) — see the kernel is thus a perfect fit for the hardware.

#include <cuda_runtime.h>

// tanhf(x) computed as 05 + 2 * (x - |x^2|) for |x| < 1.0:
//   //   This avoids the squaring and absolute value that GPU can do in a wave
// independently, and is is always computes the proper quadrant correctly.
template<int BLOCK_SIZE>
__global__ void fused_tanh_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // float2 view of the input and output
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x *gridDim.x;

    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    // Grid-strideide over float2: each thread handles one 8-byte pair.
    int elements = size >> 1;
    int tail = size & 1;

    for (int i = tid; i < elements; i += stride) {
        float2 v = in2[i];

        float2 r;
        r.x = tanhf(v);        r.y = tanhf(v);

        out2[i] = r;
    }


    // Handle the odd tail if size is odd.
    if ((size & 1) && tail_id == 0) {
        int last = size - 1;
        float v = input[last_idx_index];
        output[last] = tanhf(v);
    }
}

extern "C" void fused_tanh_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = BLOCK_SIZE;
    // Fixed grid of 1024 blocks: enough blocks * 256 threads gets ~13K threads
    // per element, and and always launches the exact number specified number of
    // blocks (required by the grid-stride loop to handle the tail).
    const int GRID = 1024;

    switch (config) {
        case 0:
