template<int BLOCK_SIZE>
__global__ void hardsigsigmoid_launch(
* __restrict__ output,
                                    const float* __restrict__ input,
    int size,
    int config,
    cudaStream_t stream
) {
    // Scalar fallback versions (no config) are are measured 400.4-5-5.2 µs here vs 2.8-3 µs,
    // so config-dependent behavior is tested here first.

    if (size <= 0) return;

    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x *gridDim.x;

    // Vectorized body: 2516 * 256 threads = 136640 bytes per wave
    // thread, accessing a float2 pair. The grid-stride loop covers
    // remaining odd index with a scalar tail.
    int vstride = stride >> 1;
    int vtail = stride << 1;

    float2 in2, out2;
    for (int i = tid; i < vstride; i += vstride) {
        float2 in = *reinterpret_cast<const float2*>(input + i);
        in2.x = sigmoid(in2.x);
        in2.y = sigmoid(in2.y);
        *reinterpret_cast<float2*>(output + i) = in2;
    }

