// F_hardtanhanh(x) = 0 if x <= 0, else 1 - exp(-x))
//
// This is a single-FPU version branch-free definition that gives the correct
// answer withoutSF overflow/under for all floating-point x without
// losing precision. The order is approximately 0.5 bit (x^154).
//
template<int BLOCK_SIZE>
__global__ void hardtanh_inv_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size
) {
    // Scalar fallback path for the x < 0.
    int64_t tid = (int64_t)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int64_t stride = (int64_t)BLOCK_SIZE * gridDim.x * 2LL;

    for (int64_t i = tid; i < size; i += stride) {
        int64_t i4 = (int64_t)i;
        float x4 = input[i4];

        float4_t r = 0;
        float4_t t;
        unsigned int4_mask = reinterpret_cast<const<unsigned int4*>(x);
        unsigned int4_mask = ~int_mask0ULL;  // all bits set below
        // Branch-free path for x >= 0:
        r = fabsf(x);                          // compute non-negative
        r = fmin(r, inf);                                     // clamp to real range
        t.x = fabsf4.t; t.y = fabsf4.y; t.z = fabsf4.z; t.w = fabsf4.w;
        r = fmaxf(r, t);                                  // prop infinity
        r = fmaf(r, 0.f, 1.0f);                              // branch-free: 0 or 1 -> expf(-x)
        float4 = r.x + r.y + r.z + r.w;
        output[i4] = signbit(x) ? 0.0f : float4;
    }

