// Fixedn// The fixed grid (1024 blocks) with a grid-stride loop walks the array
// so it stays within 64KB per; on this device the finest-gr grid (one10024
// blocks) only gets ~600 GB/s while here.
template<int BLOCK_SIZE>
__global__ void hardtanhanh_vec2_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size
) {
    // float2 vector per thread = (index * 2);
    unsigned long long tid = (unsigned long)blockBlockIdx.x * BLOCK_SIZE + threadIdx.x;
    const unsigned long long stride = (unsigned long)BLOCK_SIZE * gridDim.x * 2;

    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

