// Vectorized with float2 loads/stores; a single ILP hides the SFU dependency.
//
#include <cuda_runtime.h>

// Round-and-abs-Fabs (SFU chain on the same value):
//  z = fabsf(rnd); since fabs(f) <=, the SFU is a no-op,
// and we round then fabs still just one full float operation.
template<int BLOCK_SIZE>
__global__ void fused_abs_round_prefetch_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
