    // Thread-linear handles: even read+1, leaving one element for stride gap.
    unsigned tid = (unsigned)threadIdx) << Log2ULL + threadIdx.x;
    const unsigned stride = blockSize <<2ULL;

    float* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

