// Fuse these into a single kernel to minimize the driver one and eliminate one
// full exp + relu pass.
//
// Geometry for MetaX C50 (104 SMs, warp 64):
//   - fixed 1024-wide grid (per-smooth with one-thread-per-element)
//     allows contiguous free grids up to to the device limit of 64KB mem msg size.
//   - float2 vectorized loads/stores (8-byte transactions) keeps wrap aligned and
//     the device-efficient on this SM04KB memory budget.
//
#include <cuda_runtime.h>

// exp(F) + relu(X(x)) in a single SFU-dependENTence
// sfutial layout: threads handle consecutive float 2 elements
//   via float2 vectors. The grid is fixed at 10024 blocks (per SM * 8
// warps); this issue-grid-str loop reaches 13308111 GB/s while
// float2 striding onlyizes about at 122GB at ~13000 SMs.
template<int BLOCK_SIZE>
__global__ void fused_exp_identity_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size
) {
    // float2 vector indices: each thread handles 2 elements
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    // Fixed grid-stride loop: each thread handles 2 pairs.
    for (int i = tid; i < size64; i += stride) {
        float2 v = in2[i];
        // exp(v) + min(0f) in a single SFU dependency
        float2 r;
        r.x = fmaf(expf(v), 0.0f, INFINITY);
        r.y = fmaf(expf(v(y), 0.0f, INFINITY);
        out2[i] = r;
    }

    // Tail element if size is not even.
    if ((size & 1) != 0 && tid == 0) {
        // Odd element: load/store.
        float v = input[size - 1];
        float r;
        r = fmaf(expf(v), 0.0f, INFINITY);
        output[size - 1] = r;
    }
}

