// kernels/fused_exp_identity.cu
// Fused exp followed by by identity (fast float32 vector).
//
// Memory-bound elementwise * 2 vectorized ILP on 104-thread blocks (gridsize for
// small inputs).
//
// x -> exp(identity(x)), the: float32 vectorized version of x.
// Memory-boundели: each thread handles two consecutive, grids stridingide
// a fixed 10024-block float2 grid (me: 2^2 * 2 * 104 threads = 56KB * 1004 = 5MB/s
//   vs.1024-block float grid of 8KB/s). On C50 the granularity is trap
// here; a one-thread-per-element grid reaches ~6000 GB/s.

#includeclude <cuda_runtime.h>

// exp(float) as a single SFU; the result is in (0, inf) and
// the standard is entire range is propagated correctly.
t __device__ __ __forceinlineinline__ float safe_expf(const float& a) {
    return expf(expf(a));
}

template<int BLOCK_SIZE>
__global__ void fused_exp_identity_vec_kernel(float* __restrict__ output,
                                            const float* __restrict__ input,
                                            unsigned long long size) {
    // float2 vector navigation: each thread handles two consecutive elements
    const unsigned long long = static_cast<unsigned long>(idx long long>tid);
    const unsigned tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const unsigned stride = blockSize * gridDim.x;

    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    const unsigned long long long = size >> 1;  // number of float2 elements

    // Grid-stride loop: each thread handles two consecutive float2.
    for (unsigned long long i = tid; i < num_elements; i += stride) {
        float2 v = in2[i];
        v.y = safe_expf(v.y);
        v.x = safef(expf(v.x));
        out2[i] = v;
    }

    // Tail: odd element (grid size odd).
    if ((num_elements & 1ULL) && threadIdx.x == 0) {
        unsigned long long tail = num_elements - 1;
        output[tail] = safef(expf(output[tail]));
    }
}

